Method.Source:
    /// <summary>
    /// The Site and Warehouse Dimensions will be mandatory (enabled and not able to be disabled),
    /// </summary>
    /// <param name = "_mode"></param>
    void updateDesign(InventDimFormDesignUpdate _mode)
    {
        InventDimParm   inventDimParm;
        
        next updateDesign(_mode);

        // if user has METISPXDS role
        if (METisISPUser())
        {
            switch (_mode)
            {
                case InventDimFormDesignUpdate::Init          :
                    // CB501_ISP_Security
                    // by default Site and WMSLocationId are selected, need to force it to site and warehouse
                    //InventDimSetupGrid::initInventDimParmInventTrans(inventDimParm);
                    InventDimSetupGrid::METInitInventDimParmInventTrans(inventDimParm);

                    if (!inventDimFormSetup)
                    {
                        inventDimFormSetup  = InventDimCtrl_Frm_ActiveRightClick::newFromForm(this);
                    }
                    inventDimFormSetup.parmDimParmVisibleGrid(inventDimParm);

                    // CB501_ISP_Security
                    // Lock Site/Warehouse so they cannot be removed/unticked
                    inventDimFormSetup.parmDimParmLockedRightClick(inventDimParm);

                    inventDimFormSetup.formSetControls(true);
            }
        }
    }
